-- Mappings hold no tenant data, so they are rebuilt from this file each time.
DELETE FROM compliance.requirement_mappings;
INSERT INTO compliance.requirement_mappings (source_requirement_id, target_requirement_id, relation, notes, source)
SELECT s.id, t.id, m.relation, m.notes, 'Atheris mapping based on the text of both standards; pending ESG SME verification'
FROM (VALUES
  ('GRI', '305-1', 'ISSB_S2', 'S2-29(a)(i)(1)', 'equivalent', 'Both require absolute gross Scope 1 emissions; IFRS S2 requires the GHG Protocol and the entity-specific consolidation approach disclosed.'),
  ('GRI', '305-2', 'ISSB_S2', 'S2-29(a)(i)(2)', 'partial', 'IFRS S2 requires location-based Scope 2 plus contractual-instrument information; GRI 305-2 asks for location-based and, if applicable, market-based.'),
  ('GRI', '305-3', 'ISSB_S2', 'S2-29(a)(i)(3)', 'partial', 'IFRS S2 requires Scope 3 by category (with relief provisions); GRI 305-3 is broader in scope and less prescriptive.'),
  ('GRI', '305-5', 'ISSB_S2', 'S2-33', 'related', 'Emission reductions vs climate-related targets.'),
  ('GRI', '2-12', 'ISSB_S2', 'S2-6(a)', 'related', 'Highest governance body oversight of impacts vs board oversight of climate-related risks and opportunities.'),
  ('GRI', '2-13', 'ISSB_S2', 'S2-6(b)', 'related', 'Delegation of responsibility vs managements role.'),
  ('TCFD', 'GOV-a', 'ISSB_S2', 'S2-6(a)', 'equivalent', 'IFRS S2 incorporates the TCFD recommendations.'),
  ('TCFD', 'GOV-b', 'ISSB_S2', 'S2-6(b)', 'equivalent', 'IFRS S2 incorporates the TCFD recommendations.'),
  ('TCFD', 'STR-a', 'ISSB_S2', 'S2-10', 'equivalent', 'IFRS S2 incorporates the TCFD recommendations.'),
  ('TCFD', 'STR-b', 'ISSB_S2', 'S2-14', 'partial', 'IFRS S2 splits this across paragraphs 13-21.'),
  ('TCFD', 'STR-c', 'ISSB_S2', 'S2-22', 'equivalent', 'IFRS S2 incorporates the TCFD recommendations.'),
  ('TCFD', 'RM-a', 'ISSB_S2', 'S2-25', 'partial', 'IFRS S2 paragraph 25 covers TCFD RM a-c together.'),
  ('TCFD', 'MT-b', 'ISSB_S2', 'S2-29(a)', 'equivalent', 'IFRS S2 makes Scope 3 mandatory where TCFD said "if appropriate".'),
  ('TCFD', 'MT-c', 'ISSB_S2', 'S2-33', 'equivalent', 'IFRS S2 incorporates the TCFD recommendations.')
) AS m(sf, sc, tf, tc, relation, notes)
JOIN compliance.regulatory_frameworks sfw ON sfw.code = m.sf
JOIN compliance.framework_requirements s ON s.framework_id = sfw.id AND s.requirement_code = m.sc
JOIN compliance.regulatory_frameworks tfw ON tfw.code = m.tf
JOIN compliance.framework_requirements t ON t.framework_id = tfw.id AND t.requirement_code = m.tc;

-- Fail loudly if a mapping or parent above refers to a code that doesn't exist.
DO $$
BEGIN
  IF (SELECT count(*) FROM compliance.requirement_mappings) <> 14 THEN
    RAISE EXCEPTION 'requirement_mappings: % of 14 rows resolved', (SELECT count(*) FROM compliance.requirement_mappings);
  END IF;
END $$;
